#!/usr/bin/env node
/** The command: `dump <file>` and `get <file> <key>`. */

import { existsSync, readFileSync } from 'node:fs'
import { IniError, parse as parseIni } from './ini.js'
import { merge } from './layer.js'
import { SETTINGS, setting } from './schema.js'

const USAGE = 'usage: cli.js dump <file>|get <file> <key>'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** One INI layer, refused at its own position when the grammar rejects it. */
function iniLayer(name, path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  try {
    return { name, values: parseIni(readFileSync(path, 'utf8')) }
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { dump: 2, get: 3 }
if (argv.length !== arity[mode]) fail(USAGE)

const values = merge([iniLayer('file', argv[1])])
const raw = key => (values.has(key) ? values.get(key) : setting(key).default)
const out = []
if (mode === 'dump') {
  for (const declared of SETTINGS) out.push(`${declared.key}=${raw(declared.key)}`)
} else {
  if (setting(argv[2]) === undefined) fail(`unknown setting ${argv[2]}`)
  out.push(raw(argv[2]))
}
process.stdout.write(out.map(line => `${line}\n`).join(''))

/** The INI reader: dotted keys and the raw text of each value. */

const NAME = /^[A-Za-z0-9_.-]+$/

/** One refusal of an INI line, carrying the 1-based line and column it was read at. */
export class IniError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {number} column - the 1-based column of the raw line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, column, message) {
    super(message)
    this.name = 'IniError'
    this.line = line
    this.column = column
  }
}

/** The 1-based column of the first non-space character of `raw`. */
function indent(raw) {
  return raw.length - raw.trimStart().length + 1
}

/**
 * Parse INI text into its settings.
 * @param {string} text - the file's whole text.
 * @returns {Map<string, string>} each dotted key's raw value, in the order the file writes them.
 * @throws {IniError} on the first line the grammar refuses.
 */
export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const values = new Map()
  let section = ''
  for (const [index, raw] of lines.entries()) {
    const line = index + 1
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#') || trimmed.startsWith(';')) continue
    if (trimmed.startsWith('[')) {
      if (!trimmed.endsWith(']')) throw new IniError(line, raw.trimEnd().length + 1, 'expected "]"')
      const name = trimmed.slice(1, -1)
      if (name === '') throw new IniError(line, indent(raw) + 1, 'expected a section name')
      if (!NAME.test(name)) throw new IniError(line, indent(raw) + 1, `invalid section name ${name}`)
      section = name
      continue
    }
    const split = trimmed.indexOf('=')
    if (split === -1) throw new IniError(line, indent(raw), 'expected a section header or key = value')
    const key = trimmed.slice(0, split).trim()
    if (key === '') throw new IniError(line, indent(raw) + split, 'expected a key')
    if (!NAME.test(key)) throw new IniError(line, indent(raw), `invalid key ${key}`)
    const full = section === '' ? key : `${section}.${key}`
    if (values.has(full)) throw new IniError(line, indent(raw), `key ${full} is set twice`)
    values.set(full, trimmed.slice(split + 1).trim())
  }
  return values
}

/** Stacking layers: the last layer that sets a key wins. */

/**
 * Merge named layers, later over earlier.
 * @param {readonly {name: string, values: Map<string, string>}[]} layers - the layers, weakest first.
 * @returns {Map<string, string>} each key's winning raw text.
 */
export function merge(layers) {
  const merged = new Map()
  for (const layer of layers) {
    for (const [key, text] of layer.values) merged.set(key, text)
  }
  return merged
}

/** The settings this loader knows, their types, and the text each one defaults to. */

/** Every known setting, in ascending key order. */
export const SETTINGS = [
  { key: 'log.file', type: 'string', default: '' },
  { key: 'log.level', type: 'enum', members: ['debug', 'info', 'warn', 'error'], default: 'info' },
  { key: 'log.rotate', type: 'boolean', default: 'true' },
  { key: 'retry.attempts', type: 'integer', default: '3' },
  { key: 'retry.backoff', type: 'duration', default: '250ms' },
  { key: 'server.host', type: 'string', default: 'localhost' },
  { key: 'server.port', type: 'integer', default: '8080' },
  { key: 'server.timeout', type: 'duration', default: '30s' },
  { key: 'server.tls', type: 'boolean', default: 'false' },
  { key: 'tags', type: 'list', default: '' },
]

const BY_KEY = new Map(SETTINGS.map(declared => [declared.key, declared]))

/**
 * The setting one key names, or undefined when the schema does not know it.
 * @param {string} key - the dotted setting key.
 * @returns {{key: string, type: string, members?: string[], default: string} | undefined} the setting.
 */
export function setting(key) {
  return BY_KEY.get(key)
}

/** The repository's own suite, covering what `conflayers` already does. */

import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'

const cli = fileURLToPath(new URL('../src/cli.js', import.meta.url))
const root = fileURLToPath(new URL('../', import.meta.url))

function run(argv, stdin = '') {
  const result = spawnSync(process.execPath, [cli, ...argv], { cwd: root, encoding: 'utf8', input: stdin })
  return { code: result.status, out: result.stdout, err: result.stderr }
}

const DUMPED_BASE = [
  'log.file=/var/log/app.log',
  'log.level=warn',
  'log.rotate=true',
  'retry.attempts=5',
  'retry.backoff=250ms',
  'server.host=example.test',
  'server.port=9090',
  'server.timeout=2m',
  'server.tls=false',
  'tags=',
  '',
].join('\n')

test('dump prints every setting in ascending key order, raw', () => {
  assert.deepEqual(run(['dump', 'data/base.ini']), { code: 0, out: DUMPED_BASE, err: '' })
})

test('a setting the file leaves out falls back to its schema default', () => {
  assert.equal(run(['dump', 'data/empty.ini']).out.split('\n')[5], 'server.host=localhost')
})

test('a key before any section header keeps its own name', () => {
  assert.equal(run(['get', 'data/base.ini', 'log.file']).out, '/var/log/app.log\n')
})

test('a key inside a section is prefixed with the section name', () => {
  assert.equal(run(['get', 'data/base.ini', 'server.port']).out, '9090\n')
})

test('get prints the raw text, uncoerced', () => {
  assert.equal(run(['get', 'data/base.ini', 'server.timeout']).out, '2m\n')
})

test('dump ignores a key the schema does not know', () => {
  assert.equal(run(['get', 'data/unknown.ini', 'server.host']).out, 'other.test\n')
})

test('get refuses a key outside the schema', () => {
  assert.deepEqual(run(['get', 'data/base.ini', 'server.colour']), { code: 2, out: '', err: 'error: unknown setting server.colour\n' })
})

test('a file that is not there is refused by name', () => {
  assert.deepEqual(run(['dump', 'data/nope.ini']), { code: 2, out: '', err: 'error: cannot read data/nope.ini\n' })
})

test('a line that is neither a header nor an assignment names its column', () => {
  assert.deepEqual(run(['dump', 'data/bad-line.ini']), {
    code: 2,
    out: '',
    err: 'error: data/bad-line.ini:2:3: expected a section header or key = value\n',
  })
})

test('an unterminated section header is reported one past the line', () => {
  assert.equal(run(['dump', 'data/unterminated.ini']).err, 'error: data/unterminated.ini:1:8: expected "]"\n')
})

test('a key set twice across two openings of one section names the second line', () => {
  assert.equal(run(['dump', 'data/dup.ini']).err, 'error: data/dup.ini:8:1: key server.port is set twice\n')
})

test('a value is trimmed and an empty one stays empty', () => {
  assert.equal(run(['get', 'data/blank.ini', 'log.file']).out, '\n')
})

test('a semicolon opens a comment just as a hash does', () => {
  assert.equal(run(['get', 'data/site.ini', 'server.port']).out, '443\n')
})

test('a malformed argument list is refused with the usage line', () => {
  const failed = run(['dump'])
  assert.equal(failed.code, 2)
  assert.equal(failed.out, '')
  assert.match(failed.err, /^error: usage: cli\.js /u)
})

/** The suite for the change this task asks for: the layers, the coercion, and the positions. */

import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'

const cli = fileURLToPath(new URL('../src/cli.js', import.meta.url))
const root = fileURLToPath(new URL('../', import.meta.url))

function run(argv, stdin = '') {
  const result = spawnSync(process.execPath, [cli, ...argv], { cwd: root, encoding: 'utf8', input: stdin })
  return { code: result.status, out: result.stdout, err: result.stderr }
}

const LOADED = [
  'log.file=/var/log/app.log',
  'log.level=error',
  'log.rotate=true',
  'retry.attempts=5',
  'retry.backoff=250',
  'server.host=example.test',
  'server.port=443',
  'server.timeout=120000',
  'server.tls=true',
  'tags=web,api',
  '',
].join('\n')

test('load stacks the site file over the base file and coerces every value', () => {
  assert.deepEqual(run(['load', 'data/base.ini', 'data/site.ini']), { code: 0, out: LOADED, err: '' })
})

test('the environment layer wins over both files', () => {
  const env = 'CONF_SERVER_PORT=8443\nCONF_LOG_LEVEL=debug\n'
  const out = run(['load', 'data/base.ini', 'data/site.ini'], env).out.split('\n')
  assert.equal(out[1], 'log.level=debug')
  assert.equal(out[6], 'server.port=8443')
})

test('origin names the highest layer that set each key', () => {
  const env = 'CONF_TAGS=one\n'
  assert.equal(run(['origin', 'data/base.ini', 'data/site.ini'], env).out, [
    'log.file base',
    'log.level site',
    'log.rotate default',
    'retry.attempts base',
    'retry.backoff default',
    'server.host base',
    'server.port site',
    'server.timeout base',
    'server.tls site',
    'tags env',
    '',
  ].join('\n'))
})

test('a duration renders as whole milliseconds', () => {
  const env = 'CONF_RETRY_BACKOFF=2h\nCONF_SERVER_TIMEOUT=1500ms\n'
  const out = run(['load', 'data/empty.ini', 'data/empty.ini'], env).out.split('\n')
  assert.equal(out[4], 'retry.backoff=7200000')
  assert.equal(out[7], 'server.timeout=1500')
})

test('a list drops repeats and keeps the order it was written in', () => {
  const out = run(['load', 'data/empty.ini', 'data/site.ini']).out.split('\n')
  assert.equal(out[9], 'tags=web,api')
})

test('a value that does not fit its type is reported at the position it was written', () => {
  assert.deepEqual(run(['load', 'data/base.ini', 'data/bad-type.ini']), {
    code: 2,
    out: '',
    err: 'error: data/bad-type.ini:3:12: server.port is not an integer: eighty\n',
  })
})

test('an enum names its members in the declared order', () => {
  const env = 'CONF_LOG_LEVEL=quiet\n'
  assert.equal(
    run(['load', 'data/empty.ini', 'data/empty.ini'], env).err,
    'error: <stdin>:1:16: log.level is not one of debug|info|warn|error: quiet\n',
  )
})

test('a boolean takes only the two lowercase words', () => {
  const env = 'CONF_SERVER_TLS=True\n'
  assert.equal(run(['load', 'data/empty.ini', 'data/empty.ini'], env).err, 'error: <stdin>:1:17: server.tls is not a boolean: True\n')
})

test('a duration without a unit is refused', () => {
  const env = 'CONF_SERVER_TIMEOUT=30\n'
  assert.equal(run(['load', 'data/empty.ini', 'data/empty.ini'], env).err, 'error: <stdin>:1:21: server.timeout is not a duration: 30\n')
})

test('an empty item in a list is refused with the whole text', () => {
  const env = 'CONF_TAGS=a,,b\n'
  assert.equal(run(['load', 'data/empty.ini', 'data/empty.ini'], env).err, 'error: <stdin>:1:11: tags has an empty item: a,,b\n')
})

test('load refuses a key the schema does not know, where dump ignores it', () => {
  assert.equal(
    run(['load', 'data/unknown.ini', 'data/empty.ini']).err,
    'error: data/unknown.ini:3:12: unknown setting server.colour\n',
  )
})

test('an empty value is positioned one past the last non-space character', () => {
  const env = 'CONF_SERVER_PORT=\n'
  assert.equal(run(['load', 'data/empty.ini', 'data/empty.ini'], env).err, 'error: <stdin>:1:18: server.port is not an integer: \n')
})

test('an environment line without an equals sign is refused at its first character', () => {
  assert.deepEqual(run(['load', 'data/empty.ini', 'data/empty.ini'], '  CONF_TAGS\n'), {
    code: 2,
    out: '',
    err: 'error: <stdin>:1:3: expected NAME=VALUE\n',
  })
})

test('an environment name outside the schema is refused', () => {
  assert.equal(run(['load', 'data/empty.ini', 'data/empty.ini'], 'HOME=/root\n').err, 'error: <stdin>:1:1: unknown environment variable HOME\n')
})

test('an environment name set twice names its second line', () => {
  const env = 'CONF_TAGS=a\n# again\nCONF_TAGS=b\n'
  assert.equal(run(['load', 'data/empty.ini', 'data/empty.ini'], env).err, 'error: <stdin>:3:1: CONF_TAGS is set twice\n')
})

test('the base file is read before the site file and the site file before the environment', () => {
  assert.equal(
    run(['load', 'data/bad-line.ini', 'data/unknown.ini'], 'HOME=/root\n').err,
    'error: data/bad-line.ini:2:3: expected a section header or key = value\n',
  )
})

test('the usage line names every form', () => {
  assert.deepEqual(run(['load', 'data/base.ini']), {
    code: 2,
    out: '',
    err: 'error: usage: cli.js dump <file>|get <file> <key>|load <base> <site>|origin <base> <site>\n',
  })
})

