  { key: 'server.tls', type: 'boolean', default: 'false' },
  { key: 'tags', type: 'list', default: '' },
]

const BY_KEY = new Map(SETTINGS.map(declared => [declared.key, declared]))

/**
 * The setting one key names, or undefined when the schema does not know it.
 * @param {string} key - the dotted setting key.
 * @returns {{key: string, type: string, members?: string[], default: string} | undefined} the setting.
 */
export function setting(key) {
  return BY_KEY.get(key)
}

/** The environment variable name a schema key travels under. */
export function envName(key) {
  return `CONF_${key.toUpperCase().replace(/\./g, '_')}`
}

/** One value that does not fit its setting's declared type. */
export class CoerceError extends Error {}

const INTEGER = /^-?(0|[1-9][0-9]*)$/
const DURATION = /^([0-9]+)(ms|s|m|h)$/
const DURATION_MS = { ms: 1n, s: 1000n, m: 60000n, h: 3600000n }

/**
 * Coerce one raw text by its setting's declared type, rendering it back to text.
 * @param {{key: string, type: string, members?: string[]}} declared - the setting.
 * @param {string} text - the raw text a layer wrote, or the schema default.
 * @returns {string} the rendered value.
 * @throws {CoerceError} when `text` does not fit the declared type.
 */
export function coerce(declared, text) {
  switch (declared.type) {
    case 'string':
      return text
    case 'integer':
      if (!INTEGER.test(text)) throw new CoerceError(`${declared.key} is not an integer: ${text}`)
      return text
    case 'boolean':
      if (text !== 'true' && text !== 'false') throw new CoerceError(`${declared.key} is not a boolean: ${text}`)
      return text
    case 'enum':
      if (!declared.members.includes(text)) {
        throw new CoerceError(`${declared.key} is not one of ${declared.members.join('|')}: ${text}`)
      }
      return text
    case 'duration': {
      const match = DURATION.exec(text)
      if (!match) throw new CoerceError(`${declared.key} is not a duration: ${text}`)
      return String(BigInt(match[1]) * DURATION_MS[match[2]])
    }
    case 'list': {
      if (text === '') return ''
      const items = text.split(',').map(item => item.trim())
      if (items.some(item => item === '')) throw new CoerceError(`${declared.key} has an empty item: ${text}`)
      const seen = new Set()
      const kept = []
      for (const item of items) {
        if (seen.has(item)) continue
        seen.add(item)
        kept.push(item)
      }
      return kept.join(',')
    }
    default:
      throw new Error(`unknown type ${declared.type}`)
  }
}
"}

