{"file_path":"src/layer.js","content":"/** Stacking layers: the last layer that sets a key wins. */

/**
 * Merge named layers, later over earlier.
 * @param {readonly {name: string, source: string, values: Map<string, {text: string, line: number, column: number}>}[]} layers
 *   - the layers, weakest first.
 * @returns {Map<string, {text: string, line: number, column: number, layer: string, source: string}>}
 *   each key's winning entry, carrying which layer set it and where.
 */
export function merge(layers) {
  const merged = new Map()
  for (const layer of layers) {
    for (const [key, entry] of layer.values) merged.set(key, { ...entry, layer: layer.name, source: layer.source })
  }
  return merged
}
"}

