{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/** The command: `dump <file>`, `get <file> <key>`, `load <base> <site>` and `origin <base> <site>`. */

import { existsSync, readFileSync } from 'node:fs'
import { EnvError, parseEnv } from './env.js'
import { IniError, parse as parseIni } from './ini.js'
import { merge } from './layer.js'
import { CoerceError, SETTINGS, coerce, setting } from './schema.js'

const USAGE = 'usage: cli.js dump <file>|get <file> <key>|load <base> <site>|origin <base> <site>'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** One INI layer, refused at its own position when the grammar rejects it. */
function iniLayer(name, path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  try {
    return { name, source: path, values: parseIni(readFileSync(path, 'utf8')) }
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
}

/** The environment layer, read whole from standard input. */
function envLayer() {
  const text = readFileSync(0, 'utf8')
  try {
    return { name: 'env', source: '<stdin>', values: parseEnv(text) }
  } catch (error) {
    if (!(error instanceof EnvError)) throw error
    return fail(`<stdin>:${error.line}:${error.column}: unknown environment variable ${error.message}`.replace(
      /^unknown environment variable (expected|.+ is set twice)/u,
      '$1',
    ))
  }
}

/** Refuse the first key an INI layer sets that the schema does not know, in file order. */
function checkKnownKeys(path, values) {
  for (const [key, entry] of values) {
    if (setting(key) === undefined) fail(`${path}:${entry.line}:${entry.column}: unknown setting ${key}`)
  }
}

/** The three layers `load` and `origin` share, weakest first. */
function loadLayers(basePath, sitePath) {
  const base = iniLayer('base', basePath)
  checkKnownKeys(basePath, base.values)
  const site = iniLayer('site', sitePath)
  checkKnownKeys(sitePath, site.values)
  return merge([base, site, envLayer()])
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { dump: 2, get: 3, load: 3, origin: 3 }
if (argv.length !== arity[mode]) fail(USAGE)

const out = []
if (mode === 'dump' || mode === 'get') {
  const values = merge([iniLayer('file', argv[1])])
  const raw = key => (values.has(key) ? values.get(key).text : setting(key).default)
  if (mode === 'dump') {
    for (const declared of SETTINGS) out.push(`${declared.key}=${raw(declared.key)}`)
  } else {
    if (setting(argv[2]) === undefined) fail(`unknown setting ${argv[2]}`)
    out.push(raw(argv[2]))
  }
} else if (mode === 'origin') {
  const merged = loadLayers(argv[1], argv[2])
  for (const declared of SETTINGS) {
    const entry = merged.get(declared.key)
    out.push(`${declared.key} ${entry ? entry.layer : 'default'}`)
  }
} else if (mode === 'load') {
  const merged = loadLayers(argv[1], argv[2])
  for (const declared of SETTINGS) {
    const entry = merged.get(declared.key)
    const text = entry ? entry.text : declared.default
    try {
      out.push(`${declared.key}=${coerce(declared, text)}`)
    } catch (error) {
      if (!(error instanceof CoerceError)) throw error
      fail(entry ? `${entry.source}:${entry.line}:${entry.column}: ${error.message}` : error.message)
    }
  }
}
process.stdout.write(out.map(line => `${line}\n`).join(''))
"}

